select public.activate_cai_range('be280300-0000-4000-8000-000000000001');select public.activate_cai_range('be280300-0000-4000-8000-000000000002');select public.activate_cai_range('be280300-0000-4000-8000-000000000003');
create temp table first_invoice as select * from public.create_manual_invoice_with_items(jsonb_build_object('invoice_type','Factura','cliente_id','be280200-0000-4000-8000-000000000001','currency','HNL','issue_date',current_date-40,'fiscal_mode','Exenta'),'[{"description":"Servicio","quantity":1,"unit_price":100,"isv_rate":0}]');
update public.invoices set status='Aprobada' where id=(select invoice_id from first_invoice);
select pg_temp.assert_true((select balance=100 from public.finance_documents_at('receivable',current_date-30)),'Factura histórica antes de pagos');
create temp table old_receipt as select public.register_customer_receipt(gen_random_uuid(),'be280200-0000-4000-8000-000000000001',60,'HNL',current_date-20,'Transferencia','OLD-RECEIPT','','[]') id;
select public.allocate_customer_receipt((select id from old_receipt),gen_random_uuid(),jsonb_build_array(jsonb_build_object('document_id',(select invoice_id from first_invoice),'amount',60)));
select pg_temp.assert_true((select balance=100 from public.finance_documents_at('receivable',current_date-1)),'Aplicación de anticipo de hoy no reduce corte anterior');
select pg_temp.assert_true((select balance=40 and paid_amount=60 from public.finance_documents_at('receivable',current_date)),'Aplicación reduce corte de hoy');
select public.reverse_customer_receipt((select id from old_receipt),'Reverso de prueba');
select pg_temp.assert_true((select balance=100 from public.finance_documents_at('receivable',current_date)),'Reverso restaura saldo');
select pg_temp.assert_true((select sum(debit-credit)=100 from public.finance_movements_at('receivable',current_date)),'Movimientos y documentos concilian');

select public.import_accounting_accounts('[{"code":"1101","name":"Banco HNL","kind":"Activo"},{"code":"1102","name":"Banco USD","kind":"Activo"},{"code":"1103","name":"Clientes","kind":"Activo"},{"code":"2101","name":"Proveedores","kind":"Pasivo"},{"code":"2102","name":"Anticipos","kind":"Pasivo"},{"code":"2103","name":"Retenciones","kind":"Pasivo"},{"code":"3101","name":"Apertura","kind":"Patrimonio"},{"code":"4101","name":"Ganancia cambiaria","kind":"Ingreso"},{"code":"5101","name":"Gastos","kind":"Gasto"},{"code":"5102","name":"Pérdida cambiaria","kind":"Gasto"}]');
select public.manage_accounting_period(current_date-60,current_date);
select public.save_accounting_settings(false,null,(select jsonb_object_agg(purpose,id) from (select id,case code when '1101' then 'cash' when '1103' then 'receivable' when '2101' then 'payable' when '2102' then 'customer_advances' when '2103' then 'withholding_payable' when '4101' then 'exchange_gain' when '5101' then 'purchases' when '5102' then 'exchange_loss' end purpose from public.accounting_accounts where code not in ('1102','3101')) x));
create temp table bank_hnl_payload as select jsonb_build_object('kind','Banco','name','Banco ficticio HNL','bank','Banco ficticio','account_number','FICTICIA-001','currency','HNL','opening_date',current_date-50,'opening_amount',1000,'opening_rate',1,'gl_account_id',(select id from public.accounting_accounts where code='1101'),'opening_counter_id',(select id from public.accounting_accounts where code='3101')) p;
create temp table bank_hnl as select public.treasury_create_account('be280700-0000-4000-8000-000000000001',(select p from bank_hnl_payload)) id;
select pg_temp.assert_true(public.treasury_create_account('be280700-0000-4000-8000-000000000001',(select p from bank_hnl_payload))=(select id from bank_hnl),'Cuenta idempotente');
select pg_temp.assert_true((select count(*)=1 from public.treasury_movements) and not exists(select 1 from public.journal_entries),'Apertura una vez; no activa contabilidad');
select public.treasury_post_movement((select id from public.treasury_movements where category='Apertura'));
create temp table bank_usd as select public.treasury_create_account(gen_random_uuid(),jsonb_build_object('kind','Banco','name','Banco ficticio USD','bank','Banco ficticio','account_number','FICTICIA-002','currency','USD','opening_date',current_date-50,'opening_amount',0,'opening_rate',25,'gl_account_id',(select id from public.accounting_accounts where code='1102'),'opening_counter_id',(select id from public.accounting_accounts where code='3101'))) id;
select pg_temp.expect_error($c$select public.register_customer_receipt(gen_random_uuid(),'be280200-0000-4000-8000-000000000001',10,'HNL',current_date,'Efectivo','','','[]')$c$,'Selecciona la cuenta');
create temp table receipt_payload as select jsonb_build_object('request_id','be280700-0000-4000-8000-000000000002','cliente_id','be280200-0000-4000-8000-000000000001','amount',120,'currency','HNL','date',current_date,'method','Transferencia','reference','COBRO-FICTICIO','notes','','allocations',jsonb_build_array(jsonb_build_object('document_id',(select invoice_id from first_invoice),'amount',70))) p;
create temp table bank_receipt as select public.treasury_register_source('Recibo',(select id from bank_hnl),1,(select p from receipt_payload)) r;
select public.treasury_register_source('Recibo',(select id from bank_hnl),1,(select p from receipt_payload));
select pg_temp.assert_true((select count(*)=1 and sum(amount)=120 from public.treasury_movements where source_kind='Recibo'),'Recibo y aplicaciones: una entrada de efectivo');
select pg_temp.expect_error($c$select public.treasury_register_source('Recibo',(select id from bank_hnl),1,(select p||'{"amount":130}' from receipt_payload))$c$,'otros datos');
select public.allocate_customer_receipt((select r->>'id' from bank_receipt)::uuid,gen_random_uuid(),jsonb_build_array(jsonb_build_object('document_id',(select invoice_id from first_invoice),'amount',30)));
select pg_temp.assert_true((select count(*)=1 from public.treasury_movements where source_kind='Recibo'),'Aplicar remanente no crea efectivo');
select public.treasury_post_movement((select id from public.treasury_movements where source_kind='Recibo'));
select pg_temp.assert_true((select sum(debit-credit)=1120 from public.journal_lines where account_code='1101'),'Libro bancario refleja apertura y cobro');

create temp table cheque_payload as select jsonb_build_object('account_id',(select id from bank_hnl),'currency','HNL','amount',-100,'exchange_rate',1,'occurred_on',current_date,'value_on',current_date,'reference','CH-FICTICIO','description','Cheque pendiente','method','Cheque','category','Operación','counter_account_id',(select id from public.accounting_accounts where code='5101')) p;
create temp table cheque as select public.treasury_register_movement('be280700-0000-4000-8000-000000000003',(select p from cheque_payload)) id;
select public.treasury_register_movement('be280700-0000-4000-8000-000000000003',(select p from cheque_payload));
select public.treasury_post_movement((select id from cheque));
create temp table transfer_payload as select jsonb_build_object('from_id',(select id from bank_hnl),'to_id',(select id from bank_usd),'from_currency','HNL','to_currency','USD','date',current_date,'out_amount',250,'in_amount',10,'out_rate',1,'in_rate',25,'description','Traslado propio ficticio') p;
select public.treasury_transfer('be280700-0000-4000-8000-000000000004',(select p from transfer_payload));
select public.treasury_transfer('be280700-0000-4000-8000-000000000004',(select p from transfer_payload));
select pg_temp.assert_true((select count(*)=2 and sum(amount*exchange_rate)=0 from public.treasury_movements where category='Transferencia'),'Transferencia dos piernas sin flujo externo');
select public.treasury_post_movement((select id from public.treasury_movements where category='Transferencia' and amount<0));
select pg_temp.assert_true((select count(*)=2 and count(distinct entry_id)=1 from public.treasury_postings p join public.treasury_movements m on m.id=p.movement_id where m.category='Transferencia'),'Transferencia un solo asiento');
select pg_temp.expect_error($c$select public.create_manual_journal(gen_random_uuid(),current_date,'Intento por fuera',jsonb_build_array(jsonb_build_object('account_id',(select id from public.accounting_accounts where code='1101'),'debit',1),jsonb_build_object('account_id',(select id from public.accounting_accounts where code='5101'),'credit',1)))$c$,'desde Caja/Bancos');

create temp table lines as select jsonb_build_array(jsonb_build_object('date',current_date,'reference','COBRO-FICTICIO','description','Cobro recibido','amount',120,'currency','HNL'),jsonb_build_object('date',current_date,'reference','TRASLADO','description','Traslado a USD','amount',-250,'currency','HNL')) p;
create temp table bank_import as select public.bank_import_statement((select id from bank_hnl),'FILE-FICTICIO','Extracto ficticio',(select p from lines)) id;
select public.bank_import_statement((select id from bank_hnl),'FILE-FICTICIO','Extracto ficticio',(select p from lines));
select pg_temp.assert_true((select count(*)=2 from public.bank_statement_lines),'Reintento de extracto sin duplicar');
select pg_temp.expect_error($c$select public.bank_import_statement((select id from bank_hnl),'OTRO-FICTICIO','Solapado',(select p from lines))$c$,'coincide con un movimiento');
create temp table before_matching as select count(*) n from public.journal_entries;
create temp table match_items as select jsonb_build_array(jsonb_build_object('side','statement','id',(select id from public.bank_statement_lines where reference='COBRO-FICTICIO'),'amount',120),jsonb_build_object('side','movement','id',(select id from public.treasury_movements where source_kind='Recibo'),'amount',120)) p;
select public.bank_match('be280700-0000-4000-8000-000000000005',(select id from bank_hnl),current_date,(select p from match_items));
select public.bank_match('be280700-0000-4000-8000-000000000005',(select id from bank_hnl),current_date,(select p from match_items));
select pg_temp.expect_error($c$select public.bank_match(gen_random_uuid(),(select id from bank_hnl),current_date,(select p from match_items))$c$,'restante');
select pg_temp.assert_true((select count(*)=(select n from before_matching) from public.journal_entries),'Conciliar no genera otro asiento');
create temp table transfer_match as select jsonb_build_array(jsonb_build_object('side','statement','id',(select id from public.bank_statement_lines where reference='TRASLADO'),'amount',-250),jsonb_build_object('side','movement','id',(select id from public.treasury_movements where category='Transferencia' and amount<0),'amount',-250)) p;
select public.bank_match(gen_random_uuid(),(select id from bank_hnl),current_date,(select p from transfer_match));
create temp table recon as select public.bank_reconciliation_data((select id from bank_hnl),current_date-50,current_date,870) r;
select pg_temp.assert_true((select (r->>'book_closing')::numeric=770 and (r->>'checks')::numeric=100 and (r->>'deposits')::numeric=0 and (r->>'reconciled_bank')::numeric=770 and (r->>'difference')::numeric=0 from recon),'Banco menos cheque pendiente coincide con libros');
create temp table saved_report as select public.bank_save_reconciliation('be280700-0000-4000-8000-000000000006',(select id from bank_hnl),jsonb_build_object('from',current_date-50,'cutoff',current_date,'bank_balance',870,'prepared_by','Contador ficticio','reviewed_by','Gerencia ficticia')) id;
select public.bank_unmatch('be280700-0000-4000-8000-000000000005',current_date,'Vínculo de prueba corregido');
select pg_temp.assert_true((select (snapshot->>'difference')::numeric=0 from public.bank_reconciliation_reports where id=(select id from saved_report)),'Deshacer vínculo no altera versión guardada');
select pg_temp.assert_true((select count(*)=(select n from before_matching) from public.journal_entries),'Guardar/deshacer no crea asientos');
select pg_temp.expect_error($c$update public.treasury_movements set amount=999$c$,'permission denied');
select pg_temp.expect_error($c$update public.bank_reconciliation_reports set snapshot='{}'$c$,'permission denied');
select pg_temp.expect_error($c$select public.treasury_create_account(gen_random_uuid(),(select p||'{"opening_amount":"NaN"}' from bank_hnl_payload))$c$,'Completa');
select pg_temp.assert_true(not exists(select 1 from public.accounting_settings where automatic_posting),'No se activa contabilidad automática');
-- USD: original liability is historical; bank cash uses the actual payment rate.
select public.treasury_save_rate(gen_random_uuid(),(select id from bank_usd),current_date-1,25.9,26.1);
create temp table usd_receipt as select public.treasury_register_source('Recibo',(select id from bank_usd),26,jsonb_build_object('request_id',gen_random_uuid(),'cliente_id','be280200-0000-4000-8000-000000000001','amount',50,'currency','USD','date',current_date,'method','Transferencia','reference','USD-FICTICIO','notes','','allocations','[]'::jsonb)) r;
select public.treasury_post_movement((select id from public.treasury_movements where source_id=(select r->>'id' from usd_receipt)::uuid));
select pg_temp.assert_true((select amount=50 and exchange_rate=26 and buy_rate=25.9 and sell_rate=26.1 from public.treasury_movements where source_id=(select r->>'id' from usd_receipt)::uuid),'Tasas de compra/venta y tasa aplicada congeladas');
select public.treasury_save_rate(gen_random_uuid(),(select id from bank_usd),current_date,26.2,26.4);
select pg_temp.assert_true((select buy_rate=25.9 from public.treasury_movements where source_id=(select r->>'id' from usd_receipt)::uuid),'Cambiar TC no recalcula el movimiento');
insert into public.cuentas_pagar(id,tenant_id,proveedor_id,tipo,descripcion,monto,moneda,tipo_cambio,fecha_factura,fecha_vencimiento,status) values('be280800-0000-4000-8000-000000000001',public.current_tenant_id(),'be280600-0000-4000-8000-000000000001','AP','Compra ficticia USD',80,'USD',25,current_date-10,current_date+20,'Pendiente');
create temp table supplier_paid as select public.treasury_register_source('Pago realizado',(select id from bank_usd),26,jsonb_build_object('request_id',gen_random_uuid(),'payable_id','be280800-0000-4000-8000-000000000001','amount',40,'currency','USD','date',current_date,'method','Transferencia','reference','USD-PAY-FICTICIO','notes','')) r;
select public.treasury_post_movement((select id from public.treasury_movements where source_id=(select r->>'payment_id' from supplier_paid)::uuid));
select pg_temp.assert_true((select balance=80 from public.finance_documents_at('payable',current_date-1)) and (select balance=40 and paid_amount=40 from public.finance_documents_at('payable',current_date)),'Proveedor conserva corte antes/después del pago');
select pg_temp.assert_true((select sum(credit)=1040 from public.journal_lines l join public.journal_entries e on e.id=l.entry_id where e.source_key='supplier-payment:'||(select r->>'payment_id' from supplier_paid) and l.account_code='1102'),'Banco USD usa tasa efectiva del pago');
select pg_temp.assert_true((select sum(debit)=40 from public.journal_lines where account_code='5102'),'Diferencia cambiaria de proveedor al gasto');
select public.reverse_supplier_payment((select r->>'payment_id' from supplier_paid)::uuid,'Reverso ficticio USD');
select public.reverse_customer_receipt((select r->>'id' from usd_receipt)::uuid,'Reverso ficticio USD');
select pg_temp.assert_true((select sum(amount)=10 from public.treasury_movements where account_id=(select id from bank_usd)) and (select sum(debit-credit)=250 from public.journal_lines where account_code='1102'),'Reversos restauran saldo nativo y contable');
-- Partial clearance and in-transit deposit follow the corrected Excel formula.
select public.bank_import_statement((select id from bank_hnl),'PARTIAL-FICTICIO','Extracto parcial ficticio',jsonb_build_array(jsonb_build_object('date',current_date,'reference','PARCIAL','description','Cheque parcial','amount',-40,'currency','HNL')));
select public.bank_match(gen_random_uuid(),(select id from bank_hnl),current_date,jsonb_build_array(jsonb_build_object('side','statement','id',(select id from public.bank_statement_lines where reference='PARCIAL'),'amount',-40),jsonb_build_object('side','movement','id',(select id from cheque),'amount',-40)));
create temp table transit as select public.treasury_register_movement(gen_random_uuid(),(select p from cheque_payload)||jsonb_build_object('amount',200,'reference','DEP-FICTICIO','description','Depósito en tránsito','method','Depósito')) id;
select pg_temp.expect_error($c$select public.bank_save_reconciliation(gen_random_uuid(),(select id from bank_hnl),jsonb_build_object('from',current_date-50,'cutoff',current_date,'bank_balance',830,'prepared_by','Contador','reviewed_by','Gerencia'))$c$,'contabiliza');
select public.treasury_post_movement((select id from transit));
select pg_temp.assert_true((select (r->>'checks')::numeric=60 and (r->>'deposits')::numeric=320 and (r->>'book_closing')::numeric=970 from (select public.bank_reconciliation_data((select id from bank_hnl),current_date-50,current_date,710) r) x),'Cheque restante y depósitos pendientes sin doble asiento');
-- The receipt match was undone above: 120 of cash is again in transit, so bank
-- balance is 710; 710 - 60 + (200+120) = 970.
select pg_temp.assert_true((select (r->>'difference')::numeric=0 from (select public.bank_reconciliation_data((select id from bank_hnl),current_date-50,current_date,710) r) x),'Fórmula con cobro sin vínculo y depósito en tránsito');
select public.bank_save_reconciliation(gen_random_uuid(),(select id from bank_hnl),jsonb_build_object('from',current_date-50,'cutoff',current_date,'bank_balance',710,'prepared_by','Contador','reviewed_by','Gerencia'));
select pg_temp.assert_true((select max(version)=2 from public.bank_reconciliation_reports),'Versiones conservadas por cuenta y corte');
select public.treasury_reverse_movement((select id from transit),current_date,'Reverso ficticio de depósito');
select pg_temp.assert_true((select count(*)=1 from public.treasury_movements where reverse_of=(select id from transit)),'Reverso manual único');
select public.treasury_reverse_movement((select id from public.treasury_movements where transfer_id='be280700-0000-4000-8000-000000000004' and amount<0),current_date,'Reverso ficticio de traslado');
select pg_temp.assert_true((select sum(amount)=0 from public.treasury_movements where category='Transferencia') and (select sum(debit-credit)=0 from public.journal_lines where account_code='1102'),'Reverso de transferencia conserva ambas piernas y un solo asiento');
create temp table unposted_receipt as select public.treasury_register_source('Recibo',(select id from bank_hnl),1,jsonb_build_object('request_id',gen_random_uuid(),'cliente_id','be280200-0000-4000-8000-000000000001','amount',17,'currency','HNL','date',current_date,'method','Efectivo','reference','','notes','','allocations','[]'::jsonb)) r;
select public.reverse_customer_receipt((select r->>'id' from unposted_receipt)::uuid,'Reverso antes de contabilizar');
create temp table before_pair as select sum(debit-credit) balance from public.journal_lines where account_code='1101';
select public.treasury_post_movement((select id from public.treasury_movements where source_id=(select r->>'id' from unposted_receipt)::uuid and reverse_of is null));
select pg_temp.assert_true((select count(*)=2 from public.treasury_postings p join public.treasury_movements m on m.id=p.movement_id where m.source_id=(select r->>'id' from unposted_receipt)::uuid) and (select sum(debit-credit)=(select balance from before_pair) from public.journal_lines where account_code='1101'),'Cobro reversado sin asiento contabiliza original y reverso atómicos');
create temp table direct_invoice as select * from public.create_manual_invoice_with_items(jsonb_build_object('invoice_type','Factura','cliente_id','be280200-0000-4000-8000-000000000001','currency','USD','exchange_rate',25,'issue_date',current_date,'fiscal_mode','Exenta'),'[{"description":"Servicio ficticio USD","quantity":1,"unit_price":40,"isv_rate":0}]');
update public.invoices set status='Aprobada' where id=(select invoice_id from direct_invoice);
create temp table direct_paid as select public.treasury_register_source('Pago recibido',(select id from bank_usd),26,jsonb_build_object('request_id',gen_random_uuid(),'invoice_id',(select invoice_id from direct_invoice),'amount',40,'currency','USD','date',current_date,'fiscal_type','Exenta','point_of_sale','SPS','method','Transferencia','reference','DIRECTO-FICTICIO','notes','','splits','[]'::jsonb)) r;
select public.treasury_post_movement((select id from public.treasury_movements where source_id=(select r->>'payment_id' from direct_paid)::uuid));
select pg_temp.assert_true((select count(*)=1 and max(amount)=40 and max(exchange_rate)=26 from public.treasury_movements where source_id=(select r->>'payment_id' from direct_paid)::uuid),'Pago directo registra una entrada bancaria con su tasa');
select pg_temp.assert_true((select sum(debit)=1040 from public.journal_lines l join public.journal_entries e on e.id=l.entry_id where e.source_key='payment:'||(select r->>'payment_id' from direct_paid)||':cash' and l.account_code='1102'),'Pago directo usa cuenta bancaria USD y no caja genérica');
select * from public.reverse_invoice_payment((select r->>'payment_id' from direct_paid)::uuid,'Reverso ficticio de pago directo');
select pg_temp.assert_true((select sum(debit-credit)=0 from public.journal_lines where account_code='1102'),'Reverso de pago directo restaura cuenta bancaria');
select public.save_accounting_account('{"code":"1104","name":"Caja ficticia de configuración","kind":"Activo"}');
create temp table missing_counter as select public.treasury_create_account(gen_random_uuid(),(select p from bank_hnl_payload)||jsonb_build_object('kind','Caja','name','Caja de configuración','gl_account_id',(select id from public.accounting_accounts where code='1104'),'opening_counter_id',null,'opening_amount',5)) id;
select pg_temp.expect_error($c$select public.treasury_post_movement((select id from public.treasury_movements where account_id=(select id from missing_counter)))$c$,'contrapartida contable');
select public.treasury_configure_gl((select id from missing_counter),(select id from public.accounting_accounts where code='1104'),(select id from public.accounting_accounts where code='3101'));
select public.treasury_post_movement((select id from public.treasury_movements where account_id=(select id from missing_counter)));
select pg_temp.assert_true((select sum(debit)=5 from public.journal_lines where account_code='1104'),'Permite completar contrapartida omitida sin cambiar la apertura');
select pg_temp.expect_error($c$select public.treasury_create_account(gen_random_uuid(),(select p from bank_hnl_payload)||jsonb_build_object('gl_account_id',null,'opening_counter_id',(select id from public.accounting_accounts where code='1101')))$c$,'contrapartida de apertura');
select public.manage_accounting_period(current_date-60,current_date,true);
select pg_temp.expect_error($c$select public.treasury_reverse_movement((select id from cheque),current_date,'Período cerrado')$c$,'período contable abierto');
select pg_temp.assert_true(not exists(select 1 from public.treasury_movements where reverse_of=(select id from cheque)),'Reverso bloqueado no altera efectivo');
select set_config('request.jwt.claims','{"sub":"be280000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.assert_true((select count(*)=0 from public.treasury_accounts) and (select count(*)=0 from public.finance_history) and (select count(*)=0 from public.bank_statement_lines),'Aislamiento de tenant');
select pg_temp.expect_error($c$select public.treasury_post_movement((select id from cheque))$c$,'no disponible');
select set_config('request.jwt.claims','{"sub":"be280000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.assert_true((select count(*)=0 from public.treasury_accounts),'Ventas no ve bancos');
select pg_temp.expect_error($c$select * from public.finance_documents_at('receivable',current_date)$c$,'Sin acceso');
select pg_temp.expect_error($c$select public.treasury_register_movement(gen_random_uuid(),'{}')$c$,'Sin acceso');
select pg_temp.assert_true(not has_function_privilege('anon','public.bank_import_statement(uuid,text,text,jsonb,text)','execute') and not has_function_privilege('authenticated','public.treasury_cash_account(uuid)','execute'),'Grants mínimos');
reset role;
set constraints all immediate;
rollback;
